    /** Adds a rotation written like in Blockbench (degrees; the game has x and y the other way). */
    static void turn(ModelPart part, float x, float y, float z) {
        part.xRot -= x * Mth.DEG_TO_RAD;
        part.yRot -= y * Mth.DEG_TO_RAD;
        part.zRot += z * Mth.DEG_TO_RAD;
    }

    /** The unfolded fingers of a wing of the dragons (their turn around y, radians: from the leading edge backwards). */
    static final float[] FINGERS_SPREAD = {0.1F, 0.9F, 1.7F, 2.5F};

    /**
     * The wings of the stage V dragon: folded along the back on the ground (the rest pose of the file, the membranes of
     * the fingers folded like a fan), open in the air and beating like the wings of the dragons (the flutter of
     * {@link DragonAnimator}, at the steady pace of {@link DemonRenderState#flap}).
     * @param air 0 on the ground, 1 in the air
     */
    private void wings(DemonRenderState s, float air, float age, float ground) {
        float a = s.flap;
        float[] arm = {0.125F - Mth.cos(a) * 0.2F, 0.25F, (Mth.sin(a) + 0.125F) * 0.8F};
        float[] fore = {0, -0.5F, -(Mth.sin(a + 2) + 0.5F) * 0.75F};
        float k = air * air * (3 - 2 * air);
        for (int side = 0; side < 2; side++) {
            // the right wing of the dragons (on the -x side of the game), the left one is its mirror
            float m = side == 1 ? 1 : -1;
            blend(wingArms[side], arm[0], arm[1] * m, arm[2] * m, k);
            blend(wingForearms[side], fore[0], fore[1] * m, fore[2] * m, k);
            for (int f = 0; f < 4; f++) {
                ModelPart finger = wingFingers[side][f];
                blend(finger, 0.005F * (f + 1), FINGERS_SPREAD[f] * m, 0, k);
                finger.zScale = WingFold.FINGER_WIDTH + (1 - WingFold.FINGER_WIDTH) * k;
            }
            // folded on the ground, they breathe a little
            wingArms[side].xRot += Mth.sin(age * 0.05F + side) * 0.012F * ground;
        }
    }

    /** From the rest pose of a part (folded) towards the given rotation (radians, the space of the game). */
    private static void blend(ModelPart p, float x, float y, float z, float k) {
        p.xRot += (x - p.xRot) * k;
        p.yRot += (y - p.yRot) * k;
        p.zRot += (z - p.zRot) * k;
    }

    @Override
    public void setupAnim(DemonRenderState s) {
        super.setupAnim(s);
        float age = s.ageInTicks;
        float ground = s.ground, fly = s.fly, hover = s.hover, air = fly + hover;

        // --- walking on the four limbs (the arm of one side with the leg of the other) ------------------------------
        float w = s.walkAnimationPos * 0.5F;
        float a = Math.min(1, s.walkAnimationSpeed * 1.5F) * ground;
        for (int side = 0; side < 2; side++) {
            float legPhase = w + (side == 0 ? 0 : Mth.PI);
            float armPhase = w + (side == 0 ? Mth.PI : 0);
            turn(legs[side][0], 24 * Mth.sin(legPhase) * a, 0, 0);
            turn(legs[side][1], -18 * Math.max(0, Mth.cos(legPhase)) * a, 0, 0);
            turn(arms[side][0], 22 * Mth.sin(armPhase) * a, 0, 0);
            turn(arms[side][2], 12 * Math.max(0, Mth.cos(armPhase)) * a, 0, 0);
        }
        body.y += -1.2F * Math.abs(Mth.sin(w)) * a;
        turn(body, 0, 0, 2.5F * Mth.sin(w) * a);

        // --- the poses of the flight and of the hovering ---------------------------------------------------------------
        turn(body, -28 * fly + 18 * hover, 0, 0);
        turn(neck, 15 * fly - 8 * hover, 0, 0);
        turn(head, 13 * fly - 8 * hover, 0, 0);
        for (int side = 0; side < 2; side++) {
            turn(legs[side][0], -60 * fly - 15 * hover, 0, 0);
            turn(legs[side][1], 20 * fly + 10 * hover, 0, 0);
            turn(arms[side][0], 55 * fly + 30 * hover, 0, 0);
        }
        wings(s, Mth.clamp(air, 0, 1), age, ground);

        // --- the tails: the base sways, the three tails sway on their own, and they trail behind in the flight ----------
        turn(tailBase[0], 25 * fly - 10 * hover, 0, 0);
        for (int i = 0; i < TAIL_BASE; i++) {
            float sway = Mth.sin(age * 0.07F - i * 0.5F) * (2 + i * 0.5F);
            turn(tailBase[i], 0, sway, 0);
        }
        for (int t = 0; t < 3; t++) {
            for (int i = 0; i < TAIL_PIECES; i++) {
                float sway = Mth.sin(age * 0.09F - i * 0.6F + t * 2.1F) * (4 + i * 1.2F);
                turn(tails[t][i], 0, sway, 0);
            }
        }

        // --- the head follows the look (the neck takes a part of the turn) ---------------------------------------------
        float yaw = Mth.clamp(s.yRot, -60, 60) * Mth.DEG_TO_RAD;
        float pitch = Mth.clamp(s.xRot, -40, 50) * Mth.DEG_TO_RAD;
        neck.yRot += yaw * 0.4F;
        head.yRot += yaw * 0.6F;
        neck.xRot += pitch * 0.3F;
        head.xRot += pitch * 0.7F;

        // --- the yawn: the mouth wide open, the head rises and turns to its right with a roll, like a roaring lion -----
        float y = s.yawn;
        jaw.xRot += 0.95F * y;
        head.xRot -= 0.35F * y;
        head.yRot += 0.55F * y;
        head.zRot += 0.25F * y;

        // --- the incantation: the right hand raised high, the body bent to its left ------------------------------------
        // (the left arm turns back as much as the body turns: it keeps its place by the body, the hand down outside it,
        // instead of swinging under the chest; checked against the Blockbench file: tools/build_nether_demon.py)
        float c = s.cast;
        turn(body, 20 * c, 0, 15 * c);
        turn(arms[0][0], -20.93F * c, 8.54F * c, -12.38F * c);
        turn(neck, -8 * c, 0, 10 * c);
        turn(head, -6 * c, 0, 8 * c);
        turn(arms[1][0], 140 * c, 0, -35 * c);
        turn(arms[1][2], -20 * c, 0, 0);

        // breath and roar
        jaw.xRot += Math.max(s.jaw * 0.7F, 0.3F * c);
    }
